  for (let i = 0; i < count; i++) {
    rolls.push(Math.floor(Math.random() * CONFIG.rules.advantageDiceSides) + 1);
  }

  const minRoll = Math.min(...rolls);
  return {
    value: -minRoll,
    details: `劣势${count}d6[${rolls.join(',')}]=${-minRoll}`
  };
}

