    console.log('⚠️  移除了本地字体引用（在file://协议下可能无法加载）');
    return ''; // 移除本地字体引用
  });

  // 压缩CSS（可选）
  if (compress) {
    // 基础压缩：移除注释和多余空白
    processed = processed
      // 保留重要注释（如许可证）
