  console.log(`  ${colors.green}Saved: ${(totalReduction / 1024 / 1024).toFixed(2)}MB (${reductionPercent}%)${colors.reset}`);
}

main().catch(console.error);

#!/usr/bin/env node

const fs = require("fs")
const path = require("path")

const buildDir = path.join(__dirname, "..", ".next-build")
const outputDir = path.join(__dirname, "..", "output")
const renameIndex = process.argv.includes("--rename-index")

function publishBuildOutput(sourceDir, targetDir) {
  if (!fs.existsSync(sourceDir)) {
    return targetDir
  }

  // Next 15 static export crashes if distDir itself is named "output",
  // so we build into a temp directory and publish the final artifacts here.
  fs.rmSync(targetDir, { recursive: true, force: true })
  fs.cpSync(sourceDir, targetDir, { recursive: true })

  return targetDir
}

function removeTxtFiles(directory) {
  if (!fs.existsSync(directory)) {
    return
  }

  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const fullPath = path.join(directory, entry.name)

    if (entry.isDirectory()) {
      removeTxtFiles(fullPath)
      continue
    }

    if (entry.name.endsWith(".txt")) {
      fs.unlinkSync(fullPath)
    }
  }
}

function renameExportIndex(directory) {
  const sourcePath = path.join(directory, "index.html")
  const targetPath = path.join(directory, "车卡器入口.html")

  if (!fs.existsSync(sourcePath)) {
    return
  }

  if (fs.existsSync(targetPath)) {
    fs.unlinkSync(targetPath)
  }

  fs.renameSync(sourcePath, targetPath)
}

const finalOutputDir = publishBuildOutput(buildDir, outputDir)

removeTxtFiles(finalOutputDir)

if (fs.existsSync(targetPath)) {
    fs.unlinkSync(targetPath)
  }

  fs.renameSync(sourcePath, targetPath)
}

const finalOutputDir = publishBuildOutput(buildDir, outputDir)

removeTxtFiles(finalOutputDir)

if (renameIndex) {
  renameExportIndex(finalOutputDir)
}

#!/usr/bin/env node

const { spawnSync } = require("child_process")
const fs = require("fs")
const path = require("path")

const isLocalBuild = process.argv.includes("--local")
const nextBin = require.resolve("next/dist/bin/next")
const distDir = ".next-build"

const projectRoot = path.join(__dirname, "..")
const distDirPath = path.join(projectRoot, distDir)
const nextCacheDirPath = path.join(projectRoot, ".next")

// Next 15 occasionally crashes in webpack hashing when stale build output/cache
// is left behind, so start each local build from a clean generated state.
fs.rmSync(distDirPath, { recursive: true, force: true })
fs.rmSync(nextCacheDirPath, { recursive: true, force: true })

const env = {
  ...process.env,
  NEXT_DIST_DIR: distDir,
}

if (isLocalBuild) {
  env.LOCAL_BUILD = "true"
  env.NEXT_PUBLIC_ENABLE_CARD_MANAGER = "true"
}

const result = spawnSync(process.execPath, [nextBin, "build"], {
  stdio: "inherit",
  env,
})

if (result.status !== 0) {
  process.exit(result.status || 1)
}

// Service Worker for handling chunk loading failures
self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(clients.claim());
});

// Intercept fetch requests
self.addEventListener('fetch', (event) => {
  // Only handle /_next/static/ requests
  if (!event.request.url.includes('/_next/static/')) {
    return;
  }

  event.respondWith(
    fetch(event.request).catch((error) => {
      // If chunk loading fails, force reload the page
      console.warn('[SW] Failed to load chunk, triggering reload:', event.request.url);

      // Notify all clients to reload
      self.clients.matchAll().then((clients) => {
        clients.forEach((client) => {
          client.postMessage({
            type: 'CHUNK_LOAD_ERROR',
            url: event.request.url
          });
        });
      });

      throw error;
    })
  );
});

