/**
 * Canvas资源管理器
 */
class CanvasManager {
  private canvas: HTMLCanvasElement | null = null
  private ctx: CanvasRenderingContext2D | null = null

  create(): HTMLCanvasElement {
    this.cleanup()

    this.canvas = document.createElement('canvas')
    this.ctx = this.canvas.getContext('2d')

    if (!this.ctx) {
      throw new Error('无法创建Canvas上下文')
    }

    return this.canvas
  }

  drawImage(img: HTMLImageElement): string {
    if (!this.canvas || !this.ctx) {
      throw new Error('Canvas未初始化')
    }

    // 设置canvas尺寸
    this.canvas.width = img.naturalWidth
    this.canvas.height = img.naturalHeight

    // 清空canvas
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height)

    // 绘制图片
    this.ctx.drawImage(img, 0, 0)

}

    // 设置canvas尺寸
    this.canvas.width = img.naturalWidth
    this.canvas.height = img.naturalHeight

    // 清空canvas
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height)

    // 绘制图片
    this.ctx.drawImage(img, 0, 0)

    // 转换为Base64
    let dataURL: string
    try {
      dataURL = this.canvas.toDataURL('image/webp', 0.8)
      // 检查是否真的支持WebP
      if (!dataURL.startsWith('data:image/webp')) {
        dataURL = this.canvas.toDataURL('image/png', 0.8)
      }
    } catch (e) {
      dataURL = this.canvas.toDataURL('image/png', 0.8)
    }

    return dataURL
  }

  cleanup(): void {
    if (this.canvas) {
      // 清空canvas内容释放内存
      if (this.ctx) {
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height)
      }

      // 重置尺寸为1x1以释放GPU内存
      this.canvas.width = 1
      this.canvas.height = 1
    }

    this.canvas = null
    this.ctx = null
  }
}

/**
 * 将图片转换为Base64（优化版）
 */
function imageToBase64(img: HTMLImageElement): Promise<string> {
  return new Promise((resolve, reject) => {
    const canvasManager = new CanvasManager()

    try {
      canvasManager.create()
      const dataURL = canvasManager.drawImage(img)
      resolve(dataURL)
    } catch (error) {
      reject(error)
    } finally {
      // 确保Canvas资源被清理
      canvasManager.cleanup()

return new Promise((resolve, reject) => {
    const canvasManager = new CanvasManager()

    try {
      canvasManager.create()
      const dataURL = canvasManager.drawImage(img)
      resolve(dataURL)
    } catch (error) {
      reject(error)
    } finally {
      // 确保Canvas资源被清理
      canvasManager.cleanup()
    }
  })
}

