      processed++
      onProgress?.(processed, images.length, `转换失败: ${img.src.split('/').pop()}`)

      // 如果是内存相关错误，建议用户刷新页面
      if (error instanceof Error && error.message.includes('memory')) {
        console.error('[HTML导出] 检测到内存相关错误，建议刷新页面后重试')
