  const majorThreshold = sheetData.majorThreshold ? parseInt(sheetData.majorThreshold) : 0
  attributes.push(`重伤阈值${minorThreshold}`)
  attributes.push(`严重阈值${majorThreshold}`)

attributes.push(`恐惧上限12`)

