export function migrateSheetData(
  data: Partial<SheetData> | any, 
  _options: MigrationOptions = {}
): SheetData {
  // 1. 确保基本结构，与默认数据合并
  let migrated: SheetData = {
    ...defaultSheetData,
    ...data
