    const normalized = createDefaultGoldSlots();
    return Array.from({ length: GOLD_SLOT_LIMIT }, (_, index) => {
        if (index === 0 && gold?.[index] === undefined) {
            return normalized[index];
        }

        return Boolean(gold?.[index]);
    });
}

