        return "内置卡包";
    }

    // 使用优化的同步查找方法
    const matchedCard = getStandardCardById(card.id);
    if (matchedCard && hasSourceInfo(matchedCard)) {
        if (matchedCard.source === CardSource.BUILTIN) {
            return "内置卡包";
        }
        if (matchedCard.source === CardSource.CUSTOM) {
