                        </span>
                    </div>

                    {/* 现有存档列表 - 可滚动区域 */}
                    <div className="space-y-2 overflow-y-auto flex-1 min-h-0">
                        {characterList.map((character, index) => {
                            const characterData = loadCharacterById(character.id);
                            return (

variant="outline"
                                            onClick={() => {
