        })
      ) {
        navigateToPage("/m-sheet")
      }
    }

    redirectIfNeeded()

    const handleResize = () => {
      if (resizeTimer) {
        clearTimeout(resizeTimer)
      }

      resizeTimer = setTimeout(redirectIfNeeded, 120)
    }

    window.addEventListener("resize", handleResize)

    return () => {
      if (resizeTimer) {
        clearTimeout(resizeTimer)
      }
      window.removeEventListener("resize", handleResize)
    }
  }, [])

  return null
