interface KeywordComboboxProps {
  value: string
  onChange: (value: string) => void
  onBlur?: () => void
  keywords: string[]
  onAddKeyword: (newKeyword: string) => void
  placeholder?: string
  disabled?: boolean
}

export function KeywordCombobox({
  value,
