    // 根据卡牌类型调用相应的转换器
    const standardCard = await convertCardByType(card, card.type)
    if (standardCard === null) {
      return createEmptyCard()
    }
    return standardCard
  } catch (error) {
    console.error("[convertToStandardCardAsync] 转换卡牌失败:", error, card)
    return createEmptyCard()
  }
}

