    const state = get();
    const card = state.cards.get(cardId);

    // Check if card exists and is not from a disabled batch
    if (!card) return null;

    if (card.batchId) {
      const batch = state.batches.get(card.batchId);
      if (batch?.disabled) return null;
    }

    return card;
