      const key = '系统问题'
      if (!bySpecificCard[key]) {
        bySpecificCard[key] = []
      }
      bySpecificCard[key].push(error)
    } else if (error.cardIndex !== undefined) {
      // 按具体卡片分组：第X张[类型]卡片
      const cardTypeName = CARD_TYPE_NAMES[error.cardType as CardType]
      const key = `第${error.cardIndex + 1}张${cardTypeName}卡片`
      if (!bySpecificCard[key]) {
