              message: `种族"${种族}"有${cards.length}张卡片，但应该只有2张（类别1和类别2）`
            })
          })
        }
        return
      }

      // 检查类别
      const categories = cards.map(c => c.类别).sort()
      if (categories[0] !== 1 || categories[1] !== 2) {
        errors.push({
